components.css:
.ds-disc{position:relative;display:grid;place-items:center;width:9.5rem;aspect-ratio:1;border-radius:50%;background:var(--ampoule,#F2B233);color:var(--encre,#1E1D1B);text-align:center;font:720 1.1875rem/1.22 'Bricolage Grotesque','Arial Narrow',Arial,sans-serif;font-stretch:85%;letter-spacing:-0.01em;text-decoration:none;overflow:hidden;isolation:isolate;box-shadow:0 18px 30px -16px rgba(30,29,27,.5),0 3px 8px rgba(30,29,27,.12);transition:color .4s cubic-bezier(.16,1,.3,1)}
.ds-disc::before{content:"";position:absolute;inset:0;border-radius:50%;background:var(--encre,#1E1D1B);transform:scale(0);transition:transform .6s cubic-bezier(.16,1,.3,1);z-index:-1}
.ds-disc:hover,.ds-disc:focus-visible{color:var(--sable,#EFE7DB)}
.ds-disc:hover::before,.ds-disc:focus-visible::before{transform:scale(1.04)}
.ds-disc span{max-width:6.4em}
